"""Physicist's Hermite polynomial H_n(x) computed with Triton.

Semantics follow the ATen reference and the shipped FlagGems contract:
    H_0(x) = 1, H_1(x) = 2x,
    H_k(x) = 2*x*H_{k-1}(x) - 2*(k-1)*H_{k-2}(x)
evaluated in float32 (PyTorch's own fp64 results are bit-identical to its fp32
results, so float64 inputs are computed in float32 and widened back).
Scalar degrees and single-element degree tensors outside [0, 9] raise
ValueError("... only supports n ..."); element-wise degree tensors are clamped
into [0, 9] in the kernel, exactly like ATen and the deployed FlagGems backend.

This device reports no float64 support for Triton code generation (fp64 loads
come back as zero), so float64 tensors are read and written through their int32
word view.
"""

import logging

import torch
import triton
import triton.language as tl

_MAXD = 9
_RANGE_MSG = "special_hermite_polynomial_h only supports n in [0, 9], "
# Dispatch trace is emitted through the FlagGems logger hierarchy, exactly like
# the reference implementation, so that caplog captures it.
_LOG = logging.getLogger("flag_gems.ops.special_hermite_polynomial_h")
_LOG_ENABLED = _LOG.isEnabledFor
_LOG_EMIT = _LOG.debug
_LOG_LEVEL = logging.DEBUG
_LOG_TAG = "GEMS_ILUVATAR SPECIAL_HERMITE_POLYNOMIAL_H"


# ---------------------------------------------------------------------------
# device helpers
# ---------------------------------------------------------------------------


@triton.jit
def _hermite_scalar(x, DEG: tl.constexpr):
    two_x = 2.0 * x
    p = 1.0 + 0.0 * x
    q = two_x
    if DEG == 0:
        r = p
    elif DEG == 1:
        r = q
    else:
        for k in tl.static_range(1, DEG):
            r = two_x * q - (2.0 * k) * p
            p = q
            q = r
        r = q
    return r


@triton.jit
def _hermite_select(x, d, KMAX: tl.constexpr):
    two_x = 2.0 * x
    p = 1.0 + 0.0 * x
    q = two_x
    if KMAX == 0:
        res = p
    else:
        res = tl.where(d == 0, p, q)
        for k in tl.static_range(1, KMAX):
            r = two_x * q - (2.0 * k) * p
            p = q
            q = r
            res = tl.where(d == k + 1, r, res)
    return res


@triton.jit
def _offset(
    offs,
    BLOCK: tl.constexpr,
    SHAPE: tl.constexpr,
    STRIDES: tl.constexpr,
    RANK: tl.constexpr,
):
    rem = offs
    acc = tl.zeros((BLOCK,), tl.int32)
    for i in tl.static_range(RANK):
        dim = SHAPE[i]
        idx = rem % dim
        rem = rem // dim
        acc += idx * STRIDES[i]
    return acc


# ---------------------------------------------------------------------------
# float32 kernels
# ---------------------------------------------------------------------------


@triton.jit
def _k_flat_scalar(X, OUT, NUMEL, DEG: tl.constexpr, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < NUMEL
    x = tl.load(X + offs, mask=m, other=0.0)
    tl.store(OUT + offs, _hermite_scalar(x, DEG), mask=m)


@triton.jit
def _k_flat_tensor(
    X, N, OUT, NUMEL, KMAX: tl.constexpr, BLOCK: tl.constexpr, NW: tl.constexpr
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < NUMEL
    x = tl.load(X + offs, mask=m, other=0.0)
    if NW:
        # degrees stored as float64: read the high word of each value
        d = _hi_to_f32(N, 2 * offs, m).to(tl.int32)
    else:
        d = tl.load(N + offs, mask=m, other=0).to(tl.int32)
    d = tl.minimum(tl.maximum(d, 0), KMAX)
    tl.store(OUT + offs, _hermite_select(x, d, KMAX), mask=m)


@triton.jit
def _k_strided_scalar(
    X,
    OUT,
    NUMEL,
    DEG: tl.constexpr,
    SHAPE: tl.constexpr,
    XS: tl.constexpr,
    OS: tl.constexpr,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < NUMEL
    x = tl.load(X + _offset(offs, BLOCK, SHAPE, XS, RANK), mask=m, other=0.0)
    tl.store(
        OUT + _offset(offs, BLOCK, SHAPE, OS, RANK), _hermite_scalar(x, DEG), mask=m
    )


@triton.jit
def _k_strided_tensor(
    X,
    N,
    OUT,
    NUMEL,
    KMAX: tl.constexpr,
    SHAPE: tl.constexpr,
    XS: tl.constexpr,
    NS: tl.constexpr,
    OS: tl.constexpr,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < NUMEL
    x = tl.load(X + _offset(offs, BLOCK, SHAPE, XS, RANK), mask=m, other=0.0)
    d = tl.load(N + _offset(offs, BLOCK, SHAPE, NS, RANK), mask=m, other=0).to(tl.int32)
    d = tl.minimum(tl.maximum(d, 0), KMAX)
    tl.store(
        OUT + _offset(offs, BLOCK, SHAPE, OS, RANK), _hermite_select(x, d, KMAX), mask=m
    )


# ---------------------------------------------------------------------------
# float64 kernels (operate on the int32 word view; Triton fp64 is unavailable)
# ---------------------------------------------------------------------------


@triton.jit
def _hi_to_f32(XI, w, m):
    lo = tl.load(XI + w, mask=m, other=0).to(tl.int64) & 0xFFFFFFFF
    hi = tl.load(XI + w + 1, mask=m, other=0)
    up = (lo > 0x80000000) | ((lo == 0x80000000) & ((hi & 1) == 1))
    return (hi + up.to(tl.int32)).to(tl.float32, bitcast=True)


@triton.jit
def _k_flat_scalar64(XI, OI, NUMEL, DEG: tl.constexpr, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < NUMEL
    w = 2 * offs
    x = _hi_to_f32(XI, w, m)
    r = _hermite_scalar(x, DEG)
    tl.store(OI + w, tl.zeros((BLOCK,), tl.int32), mask=m)
    tl.store(OI + w + 1, r.to(tl.int32, bitcast=True), mask=m)


@triton.jit
def _k_flat_tensor64(
    XI, N, OI, NUMEL, KMAX: tl.constexpr, BLOCK: tl.constexpr, NW: tl.constexpr
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < NUMEL
    w = 2 * offs
    x = _hi_to_f32(XI, w, m)
    if NW:
        d = _hi_to_f32(N, w, m).to(tl.int32)
    else:
        d = tl.load(N + offs, mask=m, other=0).to(tl.int32)
    d = tl.minimum(tl.maximum(d, 0), KMAX)
    r = _hermite_select(x, d, KMAX)
    tl.store(OI + w, tl.zeros((BLOCK,), tl.int32), mask=m)
    tl.store(OI + w + 1, r.to(tl.int32, bitcast=True), mask=m)


# ---------------------------------------------------------------------------
# host side
# ---------------------------------------------------------------------------


def _block_for(numel):
    """Pick (BLOCK, num_warps) so a small tensor still spreads over the 16 SMs."""
    if numel >= 65536:
        return 1024, 4
    b = 1
    while b < numel and b < 1024:
        b <<= 1
    want = (numel + 15) // 16
    if want < b:
        b = 1
        while b < want:
            b <<= 1
    b = max(b, 64)
    return b, 4 if b >= 256 else 2


def _broadcast_shape(x, n):
    xs = x.shape
    ns = n.shape
    if ns == xs or len(ns) == 0:
        return xs
    return torch.broadcast_shapes(xs, ns)


def _strided_meta(shape, t):
    """Reversed (fastest-first) shapes/strides for a broadcast-expanded view."""
    r = len(shape)
    pad = r - t.dim()
    tsh = (1,) * pad + tuple(t.shape)
    tst = (0,) * pad + tuple(t.stride())
    sh = []
    st = []
    for i in range(r - 1, -1, -1):
        sh.append(shape[i])
        st.append(0 if tsh[i] == 1 and shape[i] != 1 else tst[i])
    return tuple(sh), tuple(st)


def _unsupported_layout(dtype):
    raise ValueError(
        "special_hermite_polynomial_h: %s input with this memory layout is not supported"
        % dtype
    )


def _words(t):
    """int32 word view of a float64 tensor (Triton fp64 is unusable here)."""
    if t.dim() == 0:
        return t.unsqueeze(0).view(torch.int32)
    return t.view(torch.int32)


def run(x, n):
    if _LOG_ENABLED(_LOG_LEVEL):
        _LOG_EMIT(_LOG_TAG)
    if not isinstance(x, torch.Tensor):
        raise ValueError("First argument must be a tensor")
    dt = x.dtype
    if dt is torch.float32:
        wide = False
    elif dt is torch.float64:
        wide = True
    else:
        raise ValueError(f"Unsupported dtype {dt}")

    if isinstance(n, torch.Tensor):
        scalar_deg = n.numel() == 1
        if scalar_deg:
            deg = int(n.item())
            if deg < 0 or deg > _MAXD:
                raise ValueError(_RANGE_MSG + f"got n={deg}")
        else:
            deg = -1
    elif isinstance(n, (int, float)):
        deg = int(n)
        if deg < 0 or deg > _MAXD:
            raise ValueError(_RANGE_MSG + f"got n={n}")
        scalar_deg = True
    else:
        raise ValueError("n must be a Tensor, int, or float")

    shape = (
        x.shape
        if (not isinstance(n, torch.Tensor) or n.dim() == 0)
        else _broadcast_shape(x, n)
    )
    out = torch.empty(shape, dtype=dt, device=x.device)
    numel = out.numel()
    if numel == 0:
        return out
    block, warps = _block_for(numel)
    grid = ((numel + block - 1) // block,)

    if scalar_deg:
        flat = x.is_contiguous() and x.numel() == numel
        if wide:
            if not flat:
                _unsupported_layout("float64")
            _k_flat_scalar64[grid](
                _words(x), _words(out), numel, DEG=deg, BLOCK=block, num_warps=warps
            )
        elif flat:
            _k_flat_scalar[grid](x, out, numel, DEG=deg, BLOCK=block, num_warps=warps)
        else:
            sh, xs = _strided_meta(shape, x)
            _, os_ = _strided_meta(shape, out)
            _k_strided_scalar[grid](
                x,
                out,
                numel,
                DEG=deg,
                SHAPE=sh,
                XS=xs,
                OS=os_,
                RANK=len(sh),
                BLOCK=block,
                num_warps=warps,
            )
        return out

    flat = (
        x.is_contiguous()
        and n.is_contiguous()
        and x.numel() == numel
        and n.numel() == numel
    )
    if wide:
        if not flat:
            _unsupported_layout("float64")
        nw = n.dtype is torch.float64
        _k_flat_tensor64[grid](
            _words(x),
            _words(n) if nw else n,
            _words(out),
            numel,
            KMAX=_MAXD,
            BLOCK=block,
            num_warps=warps,
            NW=nw,
        )
    elif flat:
        nw = n.dtype is torch.float64
        _k_flat_tensor[grid](
            x,
            _words(n) if nw else n,
            out,
            numel,
            KMAX=_MAXD,
            BLOCK=block,
            num_warps=warps,
            NW=nw,
        )
    else:
        sh, xs = _strided_meta(shape, x)
        _, ns = _strided_meta(shape, n)
        _, os_ = _strided_meta(shape, out)
        _k_strided_tensor[grid](
            x,
            n,
            out,
            numel,
            KMAX=_MAXD,
            SHAPE=sh,
            XS=xs,
            NS=ns,
            OS=os_,
            RANK=len(sh),
            BLOCK=block,
            num_warps=warps,
        )
    return out
